 32| /// A Git repository whose working tree is one agent workspace.
 33| #[derive(Clone, Debug)]
 34| pub(crate) struct WorkspaceCheckpointer {
 35|     workspace: PathBuf,
 36|     git_dir: PathBuf,
 37| }
 38| 
 39| impl WorkspaceCheckpointer {
 40|     /// Initializes (or reopens) the workspace repository and records a baseline.
 41|     ///
 42|     /// The object database always lives **beside** the workspace at
 43|     /// `workspace.git`; `workspace/.git` is only Git's small pointer file. This
 44|     /// keeps history out of the files agents enumerate and publish while still
 45|     /// allowing ordinary `git` commands run inside the workspace to discover it.
 46|     ///
 47|     /// The pointer file is write-only from the checkpointer's point of view. An
 48|     /// agent can plant a `.git` of its own (any file an agent can read it can
 49|     /// rewrite), so `initialize` never resolves its Git directory through it —
 50|     /// every Git invocation passes an explicit `--git-dir` for the out-of-band
 51|     /// path, and a planted pointer is overwritten with the real one so commands
 52|     /// the agent itself runs still discover the genuine repository.
 53|     pub(crate) fn initialize(workspace: &Path) -> anyhow::Result<Self> {
 54|         Self::initialize_with_lock_wait(workspace, true)
 55|     }
 56| 
 57|     fn initialize_with_lock_wait(workspace: &Path, wait_for_lock: bool) -> anyhow::Result<Self> {
 58|         std::fs::create_dir_all(workspace)?;
 59|         let out_of_band = workspace.with_extension("git");
 60| 
 61|         // The in-workspace `.git` is checkpoint scaffolding, not agent data: it
 62|         // exists only so ordinary `git` commands run inside the workspace
 63|         // discover the out-of-band repository. Normalize it, dropping anything
 64|         // (a pointer file or a planted directory) an agent left there — a
 65|         // planted pointer could make `git init --separate-git-dir` refuse to
 66|         // run or redirect ordinary `git` commands at a decoy repository.
 67|         let dot_git = workspace.join(".git");
 68|         if let Ok(meta) = std::fs::symlink_metadata(&dot_git) {
 69|             if meta.is_dir() {
 70|                 std::fs::remove_dir_all(&dot_git)?;
 71|             } else {
 72|                 std::fs::remove_file(&dot_git)?;
 73|             }
 74|         }
 75| 
 76|         if !out_of_band.join("HEAD").is_file() {
 77|             // Global options (`-c`, env) must precede the subcommand, so the
 78|             // isolation is applied before `init` is named.
 79|             let mut init = Command::new("git");
 80|             isolate_git(&mut init);
 81|             init.args(["init", "--quiet", "--initial-branch=checkpoints"])
 82|                 .arg("--separate-git-dir")
 83|                 .arg(&out_of_band)
 84|                 .arg(workspace);
 85|             let status = init.status()?;
 86|             require_success(status, "git init")?;
 87|         }
 88| 
 89|         // Sanitize the in-workspace pointer to the out-of-band directory, even
 90|         // when the agent planted one of its own. Never *read* an existing
 91|         // pointer to derive a Git directory: an agent-controlled pointer could
 92|         // name a repository whose hooks `git commit` would run in the host
 93|         // process (CWE-94), which `base_git`'s explicit `--git-dir` and hook
 94|         // suppression exist to make unreachable.
 95|         std::fs::write(
 96|             workspace.join(".git"),
 97|             format!("gitdir: {}\n", out_of_band.display()),
 98|         )?;
 99| 
100|         let checkpointer = Self {
101|             workspace: workspace.to_path_buf(),
102|             git_dir: out_of_band,
103|         };
104|         checkpointer.initialize_baseline(wait_for_lock)?;
105|         Ok(checkpointer)
106|     }
