13| /// The build script pulls the same file in with `include!`, so the code these
14| /// tests execute is the code that stamps the binary. The runtime reads the
15| /// finished constant and never calls the resolver, so outside a test build
16| /// this module would be dead code rather than a surface.
17| #[cfg(test)]
18| mod build_stamp;
